// Playlist/My Box interactions share the existing SPA, dialogs and players.
function libraryKindName(kind){return {original:'제작곡',cover:'커버',dubbing:'더빙'}[kind]||'콘텐츠';}
function libraryTitleCheck(form,exclude=''){
 const input=form.elements.name,status=document.createElement('small');status.className='field-help';status.setAttribute('role','status');input.after(status);let serial=0,timer;
 const check=async()=>{const ticket=++serial,value=input.value;if(!value.trim()){status.textContent='';return false;}try{const d=await api('/api/playlists/title-availability?'+new URLSearchParams({name:value,exclude:typeof exclude==='function'?exclude():exclude}),'GET',undefined,{fresh:true});if(ticket!==serial||!input.isConnected)return false;status.textContent=d.available?'사용할 수 있는 제목이에요.':'이미 사용 중인 제목이에요.';input.setCustomValidity(d.available?'':'다른 제목을 입력해주세요.');return d.available;}catch(e){if(ticket===serial&&input.isConnected)status.textContent=e.message;return false;}};
 input.addEventListener('input',()=>{++serial;input.setCustomValidity('');clearTimeout(timer);timer=setTimeout(check,350);});return check;
}
async function contentSaveMenu(tid){
 const ticket=renderId;if(!me)return askLogin();const t=trackMap.get(tid)||(await api('/api/tracks/'+encodeURIComponent(tid))).track;
 if(ticket!==renderId)return;
 if(t.kind==='cover')return boxPicker({kind:'cover',content_id:tid});
 if(!AifectPlaylist.isPlaylistEligibleTrack(t))return;
 dialog('<h2>담기</h2><div class="dialog-list"><button class="small-button" id="save-to-playlist">플레이리스트에 담기</button><button class="small-button" id="save-to-box">마이박스에 담기</button></div>');
 $('#save-to-playlist').onclick=()=>targetPlaylistPicker(tid).catch(e=>toast(e.message));$('#save-to-box').onclick=()=>boxPicker({kind:'original',content_id:tid}).catch(e=>toast(e.message));
}
async function libraryPicker({kind,item,onSelect}){
 if(!me)return askLogin();const account=me.id,box=kind==='myboxes';
 dialog(`<h2>${box?'마이박스':'플레이리스트'}에 담기</h2><form id="library-picker-search" class="ml-toolbar"><input type="search" name="q" aria-label="목록 이름 검색" placeholder="이름 검색"><button class="small-button">검색</button></form><div class="dialog-list" id="library-picker-list" role="status">불러오는 중…</div><button type="button" class="small-button" id="library-picker-more" hidden>더보기</button><button type="button" class="primary-button" id="library-picker-new">새 ${box?'마이박스':'플레이리스트'} 만들기</button>`);
 const root=$('#library-picker-list'),more=$('#library-picker-more'),form=$('#library-picker-search');let offset=0,q='',serial=0;
 const load=async(append=false)=>{const ticket=++serial;more.disabled=true;try{const d=await api('/api/me/music-library?'+new URLSearchParams({section:kind,filter:'mine',q,limit:20,offset:append?offset:0,contains:item.content_id,kind:item.kind}),'GET',undefined,{fresh:true});if(ticket!==serial||!root.isConnected||me?.id!==account)return;if(!append)root.innerHTML='';root.insertAdjacentHTML('beforeend',d.items.map(p=>`<button type="button" class="small-button" data-picker-target="${esc(p.id)}" ${p.contains?'disabled':''}>${esc(p.name)}${p.contains?' · 담김':''}</button>`).join('')||(!append?'<p class="field-help">목록이 없어요. 새로 만들어 담아보세요.</p>':''));offset=d.nextOffset;more.hidden=offset===null;}catch(e){if(root.isConnected)root.textContent=e.message;}finally{more.disabled=false;}};
 root.onclick=async e=>{const b=e.target.closest('[data-picker-target]');if(!b||b.disabled)return;b.disabled=true;try{await onSelect(b.dataset.pickerTarget);$('#dialog').close();await refreshLibrary(true);if(location.hash.includes('view=library')||location.hash.startsWith('#mybox/'))await render();}catch(err){toast(err.message);if(b.isConnected)b.disabled=false;}};
 form.onsubmit=e=>{e.preventDefault();q=form.elements.q.value;load();};more.onclick=()=>load(true);
 $('#library-picker-new').onclick=()=>{(box?myBoxDialog(null,item):playlistDialog(null,item.content_id)).catch(e=>toast(e.message));};await load();
}
async function targetPlaylistPicker(tid){return libraryPicker({kind:'playlists',item:{kind:'original',content_id:tid},onSelect:async pid=>{const d=await api(`/api/playlists/${pid}/tracks/${tid}`,'PUT');toast(d.already_added?'이미 담긴 곡이에요.':'플레이리스트에 담았어요.');}});}
async function boxPicker(item){return libraryPicker({kind:'myboxes',item,onSelect:async bid=>{const d=await api(`/api/my-boxes/${bid}/items`,'PUT',item);toast(d.already_added?'이미 담긴 콘텐츠예요.':'마이박스에 담았어요.');}});}
async function myBoxDialog(existing=null,item=null){
 if(!me)return askLogin();dialog(`<h2>${existing?'마이박스 이름 변경':'새 마이박스'}</h2><form id="mybox-form">${formField('이름','name','text',existing?.name||'','required maxlength="80"')}<p class="field-help">${icon('lock')} 나만 볼 수 있는 비공개 공간이에요.</p><button class="primary-button">${item?'만들고 담기':'저장'}</button><p class="form-error" role="alert"></p></form>`);
 const form=$('#mybox-form'),request_id=crypto.randomUUID();form.onsubmit=busyForm(form,async fd=>{const d=await api(existing?'/api/my-boxes/'+existing.id:'/api/my-boxes',existing?'PATCH':'POST',{name:fd.get('name'),...(existing?{revision:existing.revision}:{request_id,...(item?{item}:{})})});$('#dialog').close();location.hash='mybox/'+(existing?.id||d.id);await render();toast('마이박스를 저장했어요.');});
}
function myBoxCard(b){return `<article class="mybox-card"><a href="#mybox/${esc(b.id)}">${b.representative?cover(b.representative,'mini-cover'):`<span class="mybox-art">${icon('library')}</span>`}<span class="mybox-card-copy"><strong title="${esc(b.name)}">${esc(b.name)}</strong><small>제작곡 ${number(b.originals)} · 커버 ${number(b.covers)} · 더빙 ${number(b.dubbings)}</small></span><span class="mybox-private" title="비공개" aria-label="비공개">${icon('lock')}</span></a><button class="icon-button" data-box-menu="${esc(b.id)}" aria-label="${esc(b.name)} 옵션">${icon('ui-menu-action')}</button></article>`;}
let myBoxState=null;
function myBoxRows(d){return d.items.length?d.items.map(i=>{const t=i.content,key=esc(i.content_id),kind=esc(i.kind);return `<article class="mybox-item" data-box-item><div class="mybox-item-main">${i.available?`<a href="#${i.kind==='dubbing'?'dubbing':'song'}/${key}">${cover(t,'mini-cover')}<span><strong>${esc(t.title)}</strong><small>${libraryKindName(i.kind)}</small></span></a>`:`<span><strong>이용할 수 없는 콘텐츠</strong><small>${libraryKindName(i.kind)} · 삭제되었거나 접근 권한이 변경됐어요.</small></span>`}</div><div class="mybox-item-actions">${i.available?`<button class="icon-button" data-box-play="${key}" data-kind="${kind}" aria-label="${esc(t.title)} 재생">${icon('ui-play-action')}</button><button class="icon-button" data-box-copy="${key}" data-kind="${kind}" aria-label="다른 마이박스에 담기">${icon('ui-plus-action')}</button>`:''}<button class="icon-button" data-box-item-menu="${key}" data-kind="${kind}" aria-label="콘텐츠 순서 및 제거">${icon('ui-menu-action')}</button></div></article>`;}).join(''):'<p class="empty-inline">담긴 콘텐츠가 없어요. 곡이나 더빙의 담기 버튼으로 추가해보세요.</p>';}
async function myBoxView(param,raw,readApi=api){
 if(!me)return {html:gate()};const params=new URLSearchParams(raw.split('?')[1]||''),filter=params.get('filter')||'all',q=params.get('q')||'',d=await readApi('/api/my-boxes/'+encodeURIComponent(param)+'?'+new URLSearchParams({filter,q,limit:20}),'GET',undefined,{fresh:true});
 myBoxState={...d,filter,q,account:me.id};const b=d.box;
 return {html:`<section class="mybox-detail"><a class="text-link" href="#profile?view=library&section=myboxes">← 마이박스</a><div class="mp-section-head"><h1>${esc(b.name)}</h1><span class="field-help">${icon('lock')} 비공개</span></div><p class="field-help">제작곡 ${b.originals} · 커버 ${b.covers} · 더빙 ${b.dubbings}</p><div class="inline-actions"><button class="small-button" data-box-rename="${esc(b.id)}">이름 변경</button><button class="small-button" data-box-delete="${esc(b.id)}">삭제</button></div><nav class="mybox-filters" aria-label="콘텐츠 종류">${[['all','전체'],['original','제작곡'],['cover','커버'],['dubbing','더빙']].map(([key,label])=>`<a class="small-button" href="#mybox/${esc(b.id)}?${new URLSearchParams({filter:key,q})}" ${filter===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><form class="ml-toolbar" id="mybox-search"><input type="search" name="q" aria-label="마이박스 콘텐츠 검색" value="${esc(q)}" placeholder="콘텐츠 검색"><button class="small-button">검색</button></form><div id="mybox-items">${myBoxRows(d)}</div><button class="small-button ml-more" data-box-more ${d.nextOffset===null?'hidden':''}>더보기</button></section>`,tracks:[],myBox:true};
}
async function forkPlaylistDialog(pid){
 if(!me)return askLogin();const account=me.id,ticket=renderId,d=await api('/api/playlists/'+pid,'GET',undefined,{fresh:true}),p=d.playlist;if(ticket!==renderId||me?.id!==account)return;if(!p.saved)return toast('먼저 공개 플레이리스트를 저장해주세요.');
 let tracks=[...d.tracks],request_id=crypto.randomUUID();dialog(`<h2>내 플레이리스트로 편집</h2><p class="field-help">새 제목으로 저장하면 독립된 플레이리스트가 만들어져요.</p><form id="fork-playlist-form" class="playlist-editor"><div id="fork-design-preview" inert aria-label="편집본 표시 미리보기"></div>${formField('제목','name','text',p.name,'required maxlength="80"')}<label class="form-field">소개<textarea name="description" maxlength="600">${esc(p.description||'')}</textarea></label><label class="checkbox-line"><input type="checkbox" name="is_public"> 공개</label><div class="playlist-order-rows" id="fork-rows"></div><button type="button" class="small-button" id="fork-add">제작곡 찾기</button><button class="primary-button">내 플레이리스트로 저장</button><p class="form-error" role="alert"></p></form><div id="fork-candidates" class="dialog-list"></div>`);
 const form=$('#fork-playlist-form'),root=$('#fork-rows'),check=libraryTitleCheck(form),preview=()=>{$('#fork-design-preview').innerHTML=recommendedPlaylistCard({id:'',name:form.elements.name.value||'플레이리스트 제목',description:form.elements.description.value,owner_name:me.display_name||me.name,user_id:me.id,owner_profile_id:me.profile_id,tracks:tracks.length,covers:tracks.slice(0,4)});},paint=()=>{preview();root.innerHTML=tracks.map((t,i)=>`<div class="playlist-order-row"><span>${i+1}</span><div><strong>${esc(t.title)}</strong></div><button type="button" class="small-button" data-fork-move="${i}" data-direction="-1" aria-label="위로" ${i?'':'disabled'}>↑</button><button type="button" class="small-button" data-fork-move="${i}" data-direction="1" aria-label="아래로" ${i===tracks.length-1?'disabled':''}>↓</button><button type="button" class="small-button" data-fork-remove="${i}" aria-label="${esc(t.title)} 제거">제거</button></div>`).join('');};form.elements.name.addEventListener('input',preview);form.elements.description.addEventListener('input',preview);paint();
 root.onclick=e=>{const move=e.target.closest('[data-fork-move]'),remove=e.target.closest('[data-fork-remove]');if(move)tracks=AifectQueue.moveTrack(tracks,Number(move.dataset.forkMove),Number(move.dataset.direction));if(remove)tracks.splice(Number(remove.dataset.forkRemove),1);paint();};
 $('#fork-add').onclick=()=>{const candidates=$('#fork-candidates');candidates.innerHTML='<form id="fork-search" class="ml-toolbar"><input name="q" aria-label="추가할 제작곡 검색" placeholder="제작곡 검색"><button class="small-button">검색</button></form><div id="fork-results"></div>';$('#fork-search').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/playlists/candidates?limit=20&q='+encodeURIComponent(e.target.elements.q.value));if(!candidates.isConnected||me?.id!==account)return;const results=$('#fork-results');results.innerHTML=result.tracks.map(t=>`<button type="button" class="small-button" data-fork-add="${esc(t.id)}" ${tracks.some(x=>x.id===t.id)?'disabled':''}>${esc(t.title)}</button>`).join('')||'<p>검색 결과가 없어요.</p>';results.onclick=event=>{const button=event.target.closest('[data-fork-add]');if(button&&!button.disabled){tracks.push(result.tracks.find(t=>t.id===button.dataset.forkAdd));button.disabled=true;paint();}};}catch(err){toast(err.message);}};};
 form.onsubmit=busyForm(form,async fd=>{if(ticket!==renderId||me?.id!==account)throw Error('화면이나 계정이 변경됐어요. 다시 열어주세요.');if(!await check())throw Error('플레이리스트 제목을 확인해주세요.');const result=await api('/api/playlists/'+pid+'/fork','POST',{name:fd.get('name'),description:fd.get('description'),is_public:fd.has('is_public'),track_ids:tracks.map(t=>t.id),source_revision:p.revision,request_id});$('#dialog').close();await refreshLibrary(true);location.hash='playlist/'+result.id;toast('편집본을 내 플레이리스트로 저장했어요.');});
}
document.addEventListener('submit',e=>{if(e.target.id==='mybox-search'){e.preventDefault();location.hash='mybox/'+myBoxState.box.id+'?'+new URLSearchParams({filter:myBoxState.filter,q:e.target.elements.q.value});}});
document.addEventListener('click',async e=>{
 const button=e.target.closest('[data-box-add],[data-box-menu],[data-box-rename],[data-box-delete],[data-box-play],[data-box-copy],[data-box-item-menu],[data-box-move],[data-box-remove],[data-box-more],[data-playlist-save],[data-playlist-fork]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(button.dataset.libraryBusy)return;button.dataset.libraryBusy='1';button.disabled=true;
 try{
  if(button.dataset.boxAdd)await boxPicker({kind:button.dataset.kind,content_id:button.dataset.boxAdd});
  else if(button.dataset.playlistSave){if(!me)return askLogin();const saved=button.getAttribute('aria-pressed')==='true',pid=button.dataset.playlistSave;await api('/api/playlists/'+pid+'/save',saved?'DELETE':'PUT');await refreshLibrary(true);await render();toast(saved?'저장을 취소했어요.':'플레이리스트를 저장했어요.');}
  else if(button.dataset.playlistFork)await forkPlaylistDialog(button.dataset.playlistFork);
  else if(button.dataset.boxMenu){const {box}=await api('/api/my-boxes/'+button.dataset.boxMenu);myBoxState={box};dialog(`<h2>${esc(box.name)}</h2><div class="dialog-list"><button class="small-button" data-box-rename="${esc(box.id)}">이름 변경</button><button class="small-button" data-box-delete="${esc(box.id)}">삭제</button></div>`);}
  else if(button.dataset.boxRename){const {box}=await api('/api/my-boxes/'+button.dataset.boxRename);await myBoxDialog(box);}
  else if(button.dataset.boxDelete){if(confirm('이 마이박스를 삭제할까요? 원본 콘텐츠는 유지됩니다.')){await api('/api/my-boxes/'+button.dataset.boxDelete,'DELETE');$('#dialog').close();location.hash='profile?view=library&section=myboxes';await render();}}
  else if(button.dataset.boxPlay){const {box}=myBoxState;await api('/api/my-boxes/'+box.id+'?'+new URLSearchParams({filter:myBoxState.filter,q:myBoxState.q,offset:0,limit:50}),'GET',undefined,{fresh:true});if(button.dataset.kind==='dubbing')await playDubbingEdition(button.dataset.boxPlay);else{const tid=button.dataset.boxPlay,t=await api('/api/tracks/'+tid,'GET',undefined,{fresh:true});remember([t.track]);await play(tid,[t.track]);}}
  else if(button.dataset.boxCopy)await boxPicker({kind:button.dataset.kind,content_id:button.dataset.boxCopy});
  else if(button.dataset.boxItemMenu){const cid=esc(button.dataset.boxItemMenu),kind=esc(button.dataset.kind);dialog(`<h2>콘텐츠 관리</h2><div class="dialog-list"><button class="small-button" data-box-move="${cid}" data-kind="${kind}" data-direction="-1">위로 이동</button><button class="small-button" data-box-move="${cid}" data-kind="${kind}" data-direction="1">아래로 이동</button><button class="small-button" data-box-remove="${cid}" data-kind="${kind}">마이박스에서 제거</button></div>`);}
  else if(button.dataset.boxMove||button.dataset.boxRemove){const removing=!!button.dataset.boxRemove;await api('/api/my-boxes/'+myBoxState.box.id+'/'+(removing?'items':'move'),removing?'DELETE':'PUT',{kind:button.dataset.kind,content_id:button.dataset.boxRemove||button.dataset.boxMove,direction:Number(button.dataset.direction)});$('#dialog').close();await render();}
  else if(button.hasAttribute('data-box-more')){const s=myBoxState,d=await api('/api/my-boxes/'+s.box.id+'?'+new URLSearchParams({filter:s.filter,q:s.q,offset:s.nextOffset,limit:20}),'GET',undefined,{fresh:true});if(s!==myBoxState||!button.isConnected||s.account!==me?.id)return;s.items.push(...d.items);s.nextOffset=d.nextOffset;$('#mybox-items').innerHTML=myBoxRows(s);button.hidden=d.nextOffset===null;}
 }catch(err){toast(err.message);}finally{delete button.dataset.libraryBusy;button.disabled=false;}
},true);
